{
  "predictors": [
    {
      "name": "Sustainability Investment Ratio",
      "construction": "Divide the total expenditures on sustainability initiatives by total assets. Use 10-K filings to identify sustainability-related investments.",
      "rationale": "Firms investing more in sustainability may signal better risk management and long-term growth potential, appealing to socially conscious investors.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Calculate an index based on employee satisfaction scores available in company surveys and third-party reviews, normalized by industry.",
      "rationale": "Higher employee satisfaction may lead to higher productivity and lower turnover, boosting firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Measure the growth rate in the number of citations to a firm's patents over the past three years.",
      "rationale": "An increasing number of patent citations indicates valuable and influential innovations, suggesting future competitive advantage.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Trading Signal",
      "construction": "Calculate the net number of insider purchases minus sales over the last 12 months, scaled by total shares outstanding.",
      "rationale": "Net insider buying indicates management's confidence in future stock performance and undervaluation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Corporate Social Responsibility Score",
      "construction": "Aggregate scores from CSR reports across environmental, social, and governance factors, normalized by industry.",
      "rationale": "Companies with strong CSR may experience enhanced reputation and customer loyalty, leading to better financial performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration Risk",
      "construction": "Calculate the Herfindahl Index of the firm's customer base revenue concentration.",
      "rationale": "Firms with less concentrated customer bases are less vulnerable to losing major clients, reducing revenue volatility.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Product Launch Success Rate",
      "construction": "Compute the ratio of successful product launches to total launches over the past five years.",
      "rationale": "Consistently successful product launches suggest effective innovation and marketing strategies.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CEO Tenure Stability",
      "construction": "Measure the average tenure of top executives from annual proxy statements.",
      "rationale": "Longer tenures may indicate stable leadership and consistent strategic direction, likely leading to better firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Expenditure Growth",
      "construction": "Calculate the compound annual growth rate of R&D expenditures over the past three years.",
      "rationale": "Increasing R&D spending suggests a focus on innovation and potential for future earnings growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Digital Transformation Index",
      "construction": "Assess the extent and success of digital transformation initiatives through company disclosures and industry reports.",
      "rationale": "Successful digital transformation can increase operational efficiency and open new revenue streams.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
